"""Run acceptance against PlayerData.memoryStore with the repo's deterministic scheduler.

No Roblox connection, credentials, Studio, web API or persistent DataStore is used.
The vendored factory embeds the exact shipped source in an injectable lexical scope.
"""
import argparse
from pathlib import Path
import shutil
import subprocess
import tempfile

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
HEADER = """--!strict
-- Generated by run-headless.py --refresh-factory from luau/lib/server/PlayerData.luau.
-- Original module body is unchanged; injected lexical services isolate the Player lifecycle.
-- Never attach real Players to this factory's start() in the acceptance harness.
return function(game: any, task: any, Instance: any)
"""


def expected_factory():
    source = (ROOT / "luau/lib/server/PlayerData.luau").read_text(encoding="utf-8")
    # The outer factory owns the strict directive; keep every line of the module body.
    return HEADER + source.removeprefix("--!strict\n") + "\nend\n"


def bundle():
    # Reuse the exact shipped scheduler, including its queue and worker error handling.
    headless = (ROOT / "tests/headless.luau").read_text(encoding="utf-8")
    prefix = headless.split("-- MODULES --", 1)[0]
    code = prefix + """
Instance = { new = function(className)
    assert(className == "BindableEvent", "unexpected engine class " .. className)
    return { Event = {}, Fire = function() end }
end }
local runtime = { task = task, Instance = Instance, wait = task.wait, spawn = task.spawn, log = print,
    requestTypes = { update = "UpdateAsync", remove = "SetIncrementAsync" } }
"""
    for module in ("PlayerDataFactory", "Safety", "Lifecycle", "Scenarios"):
        source = (HERE / f"src/{module}.luau").read_text(encoding="utf-8")
        code += f"local {module} = (function()\n{source}\nend)()\n"
    main_source = (HERE / "src/Main.server.luau").read_text(encoding="utf-8")
    # Execute the actual entry script's refusal path, not only its Safety helper.
    code += """
local function assertMainRefusal(confirmed, allowedPlaces)
    local required = {}
    local fakeServices = {
        RunService = { IsServer = function() return true end, IsStudio = function() return true end },
        ServerScriptService = { GetAttribute = function() return confirmed end },
    }
    local game = { PlaceId = 123, GameId = 456,
        GetService = function(_, name)
            assert(fakeServices[name], "refused Main accessed unexpected service " .. name)
            return fakeServices[name]
        end }
    local script = { Parent = { Config = "Config", Safety = "Safety" } }
    local function require(name)
        table.insert(required, name)
        if name == "Safety" then return Safety end
        assert(name == "Config", "refused Main required a live-capable module")
        return { allowedPlaces = allowedPlaces, mode = "suite", runId = "" }
    end
    local warn = print
    local function main()
""" + main_source + """
    end
    main()
    assert(#required == 2, "refused Main passed its gate")
end
assertMainRefusal(nil, { [123] = 456 })
assertMainRefusal(true, {})
print("PASS Main-default-refusal: actual entry script stopped before store/service/factory acquisition")
"""
    spec = (HERE / "tests/Acceptance.spec.luau").read_text(encoding="utf-8")
    code += "local spec = (function()\n" + spec + "\nend)()\n"
    code += """
local complete = false
task.spawn(function()
    spec({ factory = PlayerDataFactory, safety = Safety, lifecycle = Lifecycle, scenarios = Scenarios,
        game = game, services = services, runtime = runtime })
    complete = true
end)
for _ = 1, 10000 do
    if #queue == 0 then break end
    table.sort(queue, function(a, b) return a.at < b.at end)
    local item = table.remove(queue, 1)
    now = item.at
    resume(item.thread, 0.01)
end
for _, err in workerErrors do print("WORKER FAIL " .. err) end
assert(#queue == 0, "headless scheduler step limit exceeded")
assert(complete and #workerErrors == 0, "acceptance headless tests failed")
print("HEADLESS ACCEPTANCE: all checks PASS, 0 worker errors (memory only; no live provider proof)")
"""
    return code


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--luau", default=shutil.which("luau"))
    parser.add_argument("--refresh-factory", action="store_true", help="refresh the unchanged vendored body before checking")
    args = parser.parse_args()
    factory = HERE / "src/PlayerDataFactory.luau"
    expected = expected_factory()
    if args.refresh_factory:
        factory.write_text(expected, encoding="utf-8", newline="\n")
    if not factory.exists() or factory.read_text(encoding="utf-8") != expected:
        parser.error("PlayerDataFactory drifted; review source then run --refresh-factory (never edit luau/lib here)")
    if not args.luau:
        parser.error("Luau CLI required; run python scripts/fetch-luau.py then pass --luau")
    with tempfile.TemporaryDirectory(prefix="moonbrick-datastore-") as temp:
        target = Path(temp) / "acceptance.luau"
        target.write_text(bundle(), encoding="utf-8", newline="\n")
        result = subprocess.run([str(Path(args.luau).resolve()), str(target)], timeout=60)
        raise SystemExit(result.returncode)


if __name__ == "__main__":
    main()
